CREATE TABLE agent_collaboration_profiles(session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload))) STRICT;
CREATE TABLE agent_collaboration_generations(id TEXT PRIMARY KEY, source_run_id TEXT NOT NULL, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, base_revision INTEGER NOT NULL CHECK(base_revision>=0), state TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE INDEX agent_collaboration_generations_session ON agent_collaboration_generations(session_id, created_at);
CREATE UNIQUE INDEX agent_collaboration_generations_running ON agent_collaboration_generations(session_id) WHERE state='running';
CREATE TABLE agent_collaboration_session_policy(session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at TEXT NOT NULL) STRICT;
CREATE TABLE agent_collaboration_graphs(id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), payload TEXT NOT NULL CHECK(json_valid(payload)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL) STRICT;
CREATE TABLE agent_collaboration_graph_members(session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, graph_id TEXT NOT NULL REFERENCES agent_collaboration_graphs(id)) STRICT;
CREATE INDEX agent_collaboration_graph_members_graph ON agent_collaboration_graph_members(graph_id, session_id);
CREATE TABLE agent_collaboration_graph_history(graph_id TEXT NOT NULL REFERENCES agent_collaboration_graphs(id), revision INTEGER NOT NULL CHECK(revision>0), snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), reason TEXT NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(graph_id,revision)) STRICT;
CREATE TRIGGER agent_collaboration_graph_member_deleted AFTER DELETE ON agent_collaboration_graph_members BEGIN UPDATE agent_collaboration_graphs SET revision=revision+1, updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id=OLD.graph_id; END;
CREATE TABLE agent_collaboration_runs(root_event_id TEXT PRIMARY KEY, workspace_id TEXT NOT NULL, used INTEGER NOT NULL CHECK(used>=0), dispatch_limit INTEGER NOT NULL CHECK(dispatch_limit>=used)) STRICT;
CREATE TABLE agent_collaboration_dispatches(call_id TEXT PRIMARY KEY, source_session_id TEXT NOT NULL, source_turn_id TEXT NOT NULL, root_event_id TEXT NOT NULL REFERENCES agent_collaboration_runs(root_event_id), origin TEXT NOT NULL CHECK(json_valid(origin)), request TEXT NOT NULL CHECK(json_valid(request)), created_at TEXT NOT NULL) STRICT;
CREATE TABLE agent_collaboration_deliveries(id TEXT PRIMARY KEY, call_id TEXT NOT NULL REFERENCES agent_collaboration_dispatches(call_id), target_session_id TEXT NOT NULL, target_turn_id TEXT UNIQUE, target_run_id TEXT UNIQUE, CHECK((target_turn_id IS NULL)=(target_run_id IS NULL)), UNIQUE(call_id,target_session_id)) STRICT;
CREATE TABLE agent_collaboration_outbox(delivery_id TEXT PRIMARY KEY REFERENCES agent_collaboration_deliveries(id), target_session_id TEXT NOT NULL) STRICT;
CREATE INDEX agent_collaboration_pending_receiver ON agent_collaboration_outbox(target_session_id);
CREATE TABLE agent_collaboration_questions(call_id TEXT PRIMARY KEY REFERENCES agent_collaboration_dispatches(call_id)) STRICT;
CREATE TABLE agent_collaboration_cancelled(delivery_id TEXT PRIMARY KEY REFERENCES agent_collaboration_deliveries(id)) STRICT;
CREATE TABLE agent_collaboration_run_controls(root_event_id TEXT PRIMARY KEY REFERENCES agent_collaboration_runs(root_event_id), revision INTEGER NOT NULL CHECK(revision>0), stopped INTEGER NOT NULL CHECK(stopped IN(0,1))) STRICT;
CREATE TABLE agent_collaboration_budget_default(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL CHECK(revision>0), dispatch_limit INTEGER NOT NULL CHECK(dispatch_limit>0)) STRICT;
CREATE INDEX agent_collaboration_dispatches_root ON agent_collaboration_dispatches(root_event_id);
CREATE INDEX agent_collaboration_deliveries_target ON agent_collaboration_deliveries(target_session_id);
CREATE INDEX agent_collaboration_dispatches_sender ON agent_collaboration_dispatches(source_session_id);
CREATE TABLE agent_collaboration_review_policy(session_id TEXT PRIMARY KEY REFERENCES sessions(id) ON DELETE CASCADE, revision INTEGER NOT NULL CHECK(revision>0), required INTEGER NOT NULL CHECK(required IN(0,1))) STRICT;
CREATE TABLE agent_collaboration_reviews(delivery_id TEXT PRIMARY KEY REFERENCES agent_collaboration_deliveries(id), reviewed_by TEXT, revised_text TEXT, reviewed_at TEXT, CHECK((reviewed_by IS NULL)=(reviewed_at IS NULL)), CHECK(reviewed_by IS NOT NULL OR revised_text IS NULL)) STRICT;
CREATE TABLE agent_collaboration_result_seen(delivery_id TEXT PRIMARY KEY REFERENCES agent_collaboration_deliveries(id), session_id TEXT NOT NULL, seen_at TEXT NOT NULL) STRICT;
CREATE TABLE agent_collaboration_retry(delivery_id TEXT PRIMARY KEY REFERENCES agent_collaboration_deliveries(id), attempts INTEGER NOT NULL CHECK(attempts>0), last_reason TEXT NOT NULL, next_at TEXT NOT NULL) STRICT;
CREATE TABLE agent_collaboration_review_settings(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL CHECK(revision>0), required INTEGER NOT NULL CHECK(required IN(0,1))) STRICT;
INSERT INTO agent_collaboration_review_settings SELECT 1,1,1 WHERE EXISTS (SELECT 1 FROM agent_collaboration_review_policy WHERE required=1);
